def likes_to_stamps(apps, schema_editor):
    """これまでの「役に立った」は、スタンプ「💡 役に立った」に"""
    PostLike = apps.get_model("chiebukuro", "PostLike")
    Reaction = apps.get_model("chiebukuro", "Reaction")
    for like in PostLike.objects.select_related("post"):
        Reaction.objects.get_or_create(
            target="post", target_id=like.post_id, user_id=like.user_id, stamp="helpful",
            defaults={"target_author_id": like.post.author_id},
        )


